//! Latent Dirichlet allocation (LDA) fitted by collapsed Gibbs sampling.
//!
//! # Model
//!
//! Blei, Ng & Jordan (2003), "Latent Dirichlet allocation", *Journal of
//! Machine Learning Research* 3, 993–1022. A corpus of `D` documents over a
//! vocabulary of `V` terms is generated by `K` topics:
//!
//! * each topic `k` is a distribution `φ_k` over terms, `φ_k ~ Dirichlet(β)`;
//! * each document `d` has topic proportions `θ_d ~ Dirichlet(α)`;
//! * each token `i` of document `d` draws a topic `z_i ~ Categorical(θ_d)`
//!   and then its term `w_i ~ Categorical(φ_{z_i})`.
//!
//! Both priors are symmetric (every component of `α` equals `alpha`, every
//! component of `β` equals `beta`).
//!
//! # Fitting
//!
//! Griffiths & Steyvers (2004), "Finding scientific topics", *PNAS* 101
//! (suppl. 1), 5228–5235. `φ` and `θ` are integrated out analytically and
//! the topic assignments `z` are sampled one token at a time from their full
//! conditional distribution
//!
//! ```text
//! p(z_i = k | z_−i, w) ∝ (n_dk + α) · (n_kw + β) / (n_k + Vβ)
//! ```
//!
//! where every count excludes token `i`: `n_dk` tokens of document `d` in
//! topic `k`, `n_kw` tokens of term `w = w_i` in topic `k`, `n_k` tokens in
//! topic `k`. Each sweep visits every token once in document order.
//! Assignments start uniformly at random.
//!
//! Given a state `z`, the posterior means of the integrated parameters are
//!
//! ```text
//! φ_kw = (n_kw + β) / (n_k + Vβ)      θ_dk = (n_dk + α) / (n_d + Kα)
//! ```
//!
//! The reported point estimates average these over the retained samples:
//! after each sweep `t` (counting from 1) with `t > burn_in` and
//! `(t − burn_in)` a multiple of `thin`. When no sweep qualifies (for
//! example `burn_in ≥ iterations`), the final state alone is used. Averaging
//! across samples assumes that topic labels do not switch within the chain
//! after burn-in, which holds in practice once the chain has settled
//! (Griffiths & Steyvers 2004, §2); a run whose chain is still moving
//! between modes should use a longer burn-in.
//!
//! Convergence is monitored by `log p(w | z)` (Griffiths & Steyvers eq. 2),
//! recorded for the starting state, every 10 sweeps and after the last one.
//!
//! Finally the topics are relabelled in decreasing order of the number of
//! tokens assigned to them in the final state (ties keep the sampler's
//! order), so topic 0 is the most used topic and labels do not depend on the
//! arbitrary labelling of the chain. The fit is a deterministic function of
//! the data and the options, including `seed`.

use stat_core::error::{Result, StatError};
use stat_core::rng::Rng;
use stat_core::special::ln_gamma;
use stat_core::summation::sum_iter;

/// Sweeps between recorded values of the log-likelihood trace.
const TRACE_EVERY: usize = 10;

/// Settings for [`fit_topic_model`].
#[derive(Debug, Clone, PartialEq)]
pub struct TopicModelOptions {
    /// Number of topics `K` (at least 1).
    pub topics: usize,
    /// Symmetric document–topic Dirichlet prior `α` (positive, finite).
    /// Default `50 / K` (Griffiths & Steyvers 2004). Larger values spread a
    /// document over more topics.
    pub alpha: f64,
    /// Symmetric topic–term Dirichlet prior `β` (positive, finite).
    /// Default 0.1. Smaller values give sparser topics.
    pub beta: f64,
    /// Number of Gibbs sweeps over all tokens (at least 1). Default 1000.
    pub iterations: usize,
    /// Sweeps discarded before samples are averaged into the estimates.
    /// Default 200.
    pub burn_in: usize,
    /// Interval, in sweeps, between averaged samples after burn-in (at
    /// least 1). Default 10.
    pub thin: usize,
    /// Seed of the random number generator. Default 1.
    pub seed: u64,
}

impl TopicModelOptions {
    /// Default settings for `topics` topics: `α = 50/K`, `β = 0.1`, 1000
    /// sweeps, 200 of burn-in, every 10th sweep averaged, seed 1. With
    /// `topics = 0`, `alpha` is infinite and fitting fails validation.
    #[must_use]
    pub fn new(topics: usize) -> Self {
        Self { topics, alpha: 50.0 / topics as f64, beta: 0.1, iterations: 1000, burn_in: 200, thin: 10, seed: 1 }
    }
}

/// A fitted topic model (see the [module documentation](self)).
#[derive(Debug, Clone, PartialEq)]
pub struct TopicModel {
    /// Topic–term probabilities `φ`: `K` rows of `V` probabilities, each row
    /// summing to 1. Row `k` is topic `k` after relabelling by size.
    pub topic_term: Vec<Vec<f64>>,
    /// Document–topic proportions `θ`: `D` rows of `K` proportions, each
    /// summing to 1. An empty document gets the prior mean, `1/K` each.
    pub document_topic: Vec<Vec<f64>>,
    /// Convergence trace: `(sweep, log p(w | z))` for the starting state
    /// (sweep 0), every 10 sweeps and the last sweep.
    pub log_likelihood: Vec<(usize, f64)>,
    /// Topic of each token in the final state, parallel to the documents.
    pub assignments: Vec<Vec<usize>>,
    /// Number of tokens assigned to each topic in the final state
    /// (non-increasing by construction of the labels).
    pub topic_tokens: Vec<usize>,
    /// Number of averaged samples behind `topic_term` and `document_topic`.
    pub samples: usize,
    /// Vocabulary size `V`.
    pub n_terms: usize,
    /// The options used.
    pub options: TopicModelOptions,
}

impl TopicModel {
    /// The `n` most probable terms of topic `k`, as `(term id, φ_kw)` in
    /// decreasing order of probability (ties by term id). Returns an empty
    /// list when `k` is not a topic; fewer than `n` when `n > V`.
    #[must_use]
    pub fn top_terms(&self, k: usize, n: usize) -> Vec<(usize, f64)> {
        let Some(row) = self.topic_term.get(k) else {
            return Vec::new();
        };
        let mut terms: Vec<(usize, f64)> = row.iter().copied().enumerate().collect();
        terms.sort_by(|a, b| b.1.total_cmp(&a.1).then(a.0.cmp(&b.0)));
        terms.truncate(n);
        terms
    }

    /// Perplexity of the fitted documents,
    /// `exp(−Σ_d Σ_{i∈d} ln Σ_k θ_dk φ_k,w_i / N)` with `N` the number of
    /// tokens. `documents` must have one entry per fitted document (usually
    /// the training corpus itself, or held-out tokens of the same
    /// documents). Lower is better; a model no better than uniform has
    /// perplexity `V`.
    ///
    /// # Errors
    /// `InvalidArgument` when the number of documents differs from the fit
    /// or a term id is not below `V`; `InsufficientData` when there are no
    /// tokens.
    pub fn perplexity(&self, documents: &[Vec<usize>]) -> Result<f64> {
        if documents.len() != self.document_topic.len() {
            return Err(invalid(format!(
                "perplexity needs {} documents (one per fitted document), got {}",
                self.document_topic.len(),
                documents.len()
            )));
        }
        check_terms(documents, self.n_terms)?;
        let n: usize = documents.iter().map(Vec::len).sum();
        if n == 0 {
            return Err(StatError::InsufficientData { required: 1, found: 0 });
        }
        let log_sum = sum_iter(documents.iter().zip(&self.document_topic).flat_map(|(doc, theta)| {
            doc.iter().map(move |&w| {
                let p: f64 = theta.iter().zip(&self.topic_term).map(|(t, phi)| t * phi[w]).sum();
                p.ln()
            })
        }));
        Ok((-log_sum / n as f64).exp())
    }
}

/// Posterior-mean parameters `φ` and `θ` of a single state `z`.
#[derive(Debug, Clone, PartialEq)]
pub struct TopicEstimates {
    /// `φ_kw = (n_kw + β) / (n_k + Vβ)`, `K × V`.
    pub topic_term: Vec<Vec<f64>>,
    /// `θ_dk = (n_dk + α) / (n_d + Kα)`, `D × K`.
    pub document_topic: Vec<Vec<f64>>,
}

/// Fit latent Dirichlet allocation by collapsed Gibbs sampling (see the
/// [module documentation](self) for the model, sampler and estimates).
///
/// `documents` holds each document as a sequence of term ids below
/// `n_terms`; empty documents are allowed.
///
/// # Errors
/// `InvalidArgument` when `topics`, `iterations` or `thin` is 0, `alpha` or
/// `beta` is not positive and finite, a term id is not below `n_terms`, or
/// the corpus has more than `u32::MAX` tokens; `InsufficientData` when the
/// corpus has no tokens.
pub fn fit_topic_model(documents: &[Vec<usize>], n_terms: usize, options: &TopicModelOptions) -> Result<TopicModel> {
    validate_options(options)?;
    check_terms(documents, n_terms)?;
    let total: usize = documents.iter().map(Vec::len).sum();
    if total == 0 {
        return Err(StatError::InsufficientData { required: 1, found: 0 });
    }
    if u32::try_from(total).is_err() {
        return Err(invalid(format!("the corpus has {total} tokens; at most {} are supported", u32::MAX)));
    }
    let k_topics = options.topics;
    let mut rng = Rng::new(options.seed);
    let mut state = State::new(documents, n_terms, k_topics);
    for (d, doc) in documents.iter().enumerate() {
        for &w in doc {
            let k = rng.below(k_topics);
            state.z.push(k as u32);
            state.add(d, w, k);
        }
    }

    let mut trace = vec![(0, state.log_likelihood(options.beta))];
    let mut phi_sum = vec![0.0; k_topics * n_terms];
    let mut theta_sum = vec![0.0; documents.len() * k_topics];
    let mut samples = 0usize;
    let mut weights = vec![0.0; k_topics];
    for sweep in 1..=options.iterations {
        state.sweep(documents, options, &mut weights, &mut rng);
        if sweep % TRACE_EVERY == 0 || sweep == options.iterations {
            trace.push((sweep, state.log_likelihood(options.beta)));
        }
        if sweep > options.burn_in && (sweep - options.burn_in) % options.thin == 0 {
            state.accumulate(options, &mut phi_sum, &mut theta_sum);
            samples += 1;
        }
    }
    if samples == 0 {
        state.accumulate(options, &mut phi_sum, &mut theta_sum);
        samples = 1;
    }

    // Relabel topics by decreasing final token count (stable for ties).
    let mut order: Vec<usize> = (0..k_topics).collect();
    order.sort_by(|&a, &b| state.n_k[b].cmp(&state.n_k[a]));
    let mut label = vec![0usize; k_topics];
    for (new, &old) in order.iter().enumerate() {
        label[old] = new;
    }
    let scale = 1.0 / samples as f64;
    let topic_term =
        order.iter().map(|&k| phi_sum[k * n_terms..(k + 1) * n_terms].iter().map(|s| s * scale).collect()).collect();
    let document_topic =
        theta_sum.chunks(k_topics).map(|row| order.iter().map(|&k| row[k] * scale).collect()).collect();
    let mut flat = state.z.iter();
    let assignments = documents
        .iter()
        .map(|doc| doc.iter().map(|_| flat.next().map_or(0, |&k| label[k as usize])).collect())
        .collect();
    let topic_tokens = order.iter().map(|&k| state.n_k[k] as usize).collect();
    Ok(TopicModel {
        topic_term,
        document_topic,
        log_likelihood: trace,
        assignments,
        topic_tokens,
        samples,
        n_terms,
        options: options.clone(),
    })
}

/// `log p(w | z)` for given assignments (Griffiths & Steyvers 2004, eq. 2):
///
/// ```text
/// K [lnΓ(Vβ) − V lnΓ(β)] + Σ_k [ Σ_w lnΓ(n_kw + β) − lnΓ(n_k + Vβ) ]
/// ```
///
/// the marginal probability of the words once the topic–term distributions
/// are integrated out under a symmetric `Dirichlet(β)` prior.
///
/// # Errors
/// `InvalidArgument` when `topics` is 0, `beta` is not positive and finite,
/// a term id is not below `n_terms`, or `assignments` does not match the
/// shape of `documents` or holds a topic not below `topics`.
pub fn log_likelihood_of(
    documents: &[Vec<usize>],
    assignments: &[Vec<usize>],
    n_terms: usize,
    topics: usize,
    beta: f64,
) -> Result<f64> {
    check_prior("beta", beta)?;
    let state = State::from_assignments(documents, assignments, n_terms, topics)?;
    Ok(state.log_likelihood(beta))
}

/// `log p(z)` for given assignments: the probability of the assignments
/// once the document–topic proportions are integrated out under a symmetric
/// `Dirichlet(α)` prior,
///
/// ```text
/// D [lnΓ(Kα) − K lnΓ(α)] + Σ_d [ Σ_k lnΓ(n_dk + α) − lnΓ(n_d + Kα) ]
/// ```
///
/// With [`log_likelihood_of`] it gives the joint `log p(w, z)`, to which the
/// sampler's full conditional is proportional.
///
/// # Errors
/// As [`log_likelihood_of`], with `alpha` in place of `beta`.
pub fn log_prior_of(documents: &[Vec<usize>], assignments: &[Vec<usize>], topics: usize, alpha: f64) -> Result<f64> {
    check_prior("alpha", alpha)?;
    let n_terms = documents.iter().flatten().max().map_or(0, |&w| w + 1);
    let state = State::from_assignments(documents, assignments, n_terms, topics)?;
    Ok(state.log_prior(alpha))
}

/// Posterior means `φ` and `θ` given one state `z` (formulas on
/// [`TopicEstimates`]).
///
/// # Errors
/// As [`log_likelihood_of`], and for `alpha` as for `beta`.
pub fn estimates_from_assignments(
    documents: &[Vec<usize>],
    assignments: &[Vec<usize>],
    n_terms: usize,
    topics: usize,
    alpha: f64,
    beta: f64,
) -> Result<TopicEstimates> {
    check_prior("alpha", alpha)?;
    check_prior("beta", beta)?;
    let state = State::from_assignments(documents, assignments, n_terms, topics)?;
    let options = TopicModelOptions { alpha, beta, ..TopicModelOptions::new(topics) };
    let mut phi = vec![0.0; topics * n_terms];
    let mut theta = vec![0.0; documents.len() * topics];
    state.accumulate(&options, &mut phi, &mut theta);
    Ok(TopicEstimates {
        topic_term: if n_terms == 0 {
            vec![Vec::new(); topics]
        } else {
            phi.chunks(n_terms).map(<[f64]>::to_vec).collect()
        },
        document_topic: theta.chunks(topics).map(<[f64]>::to_vec).collect(),
    })
}

/// Unnormalised full conditional of one token's topic,
/// `p_k = (n_dk + α)(n_kw + β)/(n_k + Vβ)`, written as running sums
/// `cumulative[k] = p_0 + … + p_k` (ready for [`draw`]), from counts that already
/// exclude the token: `doc_topic` is `n_d·` (length `K`), `term_topic` is
/// `n_·w` (length `K`), and `inverse_topic` holds `1/(n_k + Vβ)` (kept up
/// to date by the sampler so the inner loop does not divide). Returns the
/// total, `cumulative[K − 1]`.
pub(crate) fn full_conditional(
    doc_topic: &[u32],
    term_topic: &[u32],
    inverse_topic: &[f64],
    alpha: f64,
    beta: f64,
    cumulative: &mut [f64],
) -> f64 {
    let mut total = 0.0;
    for (((out, &ndk), &nkw), &inv) in cumulative.iter_mut().zip(doc_topic).zip(term_topic).zip(inverse_topic) {
        total += (f64::from(ndk) + alpha) * (f64::from(nkw) + beta) * inv;
        *out = total;
    }
    total
}

/// Sampler state: assignments and count tables in flat arrays.
struct State {
    /// Number of topics `K`.
    k: usize,
    /// Vocabulary size `V`.
    v: usize,
    /// Topic of each token, documents concatenated.
    z: Vec<u32>,
    /// `n_dk`, document-major (`D × K`).
    n_dk: Vec<u32>,
    /// `n_kw`, term-major (`V × K`) so one token reads `K` adjacent counts.
    n_wk: Vec<u32>,
    /// `n_k`.
    n_k: Vec<u32>,
    /// `n_d`.
    n_d: Vec<u32>,
}

impl State {
    fn new(documents: &[Vec<usize>], v: usize, k: usize) -> Self {
        Self {
            k,
            v,
            z: Vec::with_capacity(documents.iter().map(Vec::len).sum()),
            n_dk: vec![0; documents.len() * k],
            n_wk: vec![0; v * k],
            n_k: vec![0; k],
            n_d: vec![0; documents.len()],
        }
    }

    fn from_assignments(documents: &[Vec<usize>], assignments: &[Vec<usize>], v: usize, k: usize) -> Result<Self> {
        if k == 0 {
            return Err(invalid("the number of topics must be at least 1".into()));
        }
        check_terms(documents, v)?;
        if assignments.len() != documents.len() {
            return Err(invalid(format!("{} assignment lists for {} documents", assignments.len(), documents.len())));
        }
        let mut state = Self::new(documents, v, k);
        for (d, (doc, zd)) in documents.iter().zip(assignments).enumerate() {
            if doc.len() != zd.len() {
                return Err(invalid(format!("document {d} has {} tokens but {} assignments", doc.len(), zd.len())));
            }
            for (&w, &t) in doc.iter().zip(zd) {
                if t >= k {
                    return Err(invalid(format!("topic {t} in document {d} is not below {k}")));
                }
                state.z.push(t as u32);
                state.add(d, w, t);
            }
        }
        Ok(state)
    }

    fn add(&mut self, d: usize, w: usize, t: usize) {
        self.n_dk[d * self.k + t] += 1;
        self.n_wk[w * self.k + t] += 1;
        self.n_k[t] += 1;
        self.n_d[d] += 1;
    }

    /// One Gibbs sweep over every token in document order.
    fn sweep(&mut self, documents: &[Vec<usize>], options: &TopicModelOptions, weights: &mut [f64], rng: &mut Rng) {
        let k = self.k;
        let (alpha, beta) = (options.alpha, options.beta);
        let v_beta = self.v as f64 * beta;
        let mut inverse: Vec<f64> = self.n_k.iter().map(|&n| 1.0 / (f64::from(n) + v_beta)).collect();
        let mut i = 0;
        for (d, doc) in documents.iter().enumerate() {
            let doc_row = d * k..(d + 1) * k;
            for &w in doc {
                let old = self.z[i] as usize;
                let term_row = w * k..(w + 1) * k;
                self.n_dk[d * k + old] -= 1;
                self.n_wk[w * k + old] -= 1;
                self.n_k[old] -= 1;
                inverse[old] = 1.0 / (f64::from(self.n_k[old]) + v_beta);
                let total =
                    full_conditional(&self.n_dk[doc_row.clone()], &self.n_wk[term_row], &inverse, alpha, beta, weights);
                let new = draw(weights, total * rng.next_f64());
                self.n_dk[d * k + new] += 1;
                self.n_wk[w * k + new] += 1;
                self.n_k[new] += 1;
                inverse[new] = 1.0 / (f64::from(self.n_k[new]) + v_beta);
                self.z[i] = new as u32;
                i += 1;
            }
        }
    }

    /// Add the current state's `φ` (`K × V`, topic-major) and `θ` (`D × K`)
    /// to running sums.
    fn accumulate(&self, options: &TopicModelOptions, phi: &mut [f64], theta: &mut [f64]) {
        let (k, v) = (self.k, self.v);
        let (alpha, beta) = (options.alpha, options.beta);
        let v_beta = v as f64 * beta;
        for t in 0..k {
            let denom = f64::from(self.n_k[t]) + v_beta;
            for w in 0..v {
                phi[t * v + w] += (f64::from(self.n_wk[w * k + t]) + beta) / denom;
            }
        }
        let k_alpha = k as f64 * alpha;
        for (d, &nd) in self.n_d.iter().enumerate() {
            let denom = f64::from(nd) + k_alpha;
            for t in 0..k {
                theta[d * k + t] += (f64::from(self.n_dk[d * k + t]) + alpha) / denom;
            }
        }
    }

    /// `log p(w | z)` (Griffiths & Steyvers eq. 2). Zero counts contribute
    /// `lnΓ(β)` each, so they are counted rather than evaluated.
    fn log_likelihood(&self, beta: f64) -> f64 {
        let (k, v) = (self.k, self.v);
        let v_beta = v as f64 * beta;
        let ln_gamma_beta = ln_gamma(beta);
        let mut zeros = 0usize;
        let mut terms = Vec::with_capacity(2 * k + 1);
        let mut nonzero = Vec::new();
        for t in 0..k {
            for w in 0..v {
                let n = self.n_wk[w * k + t];
                if n == 0 {
                    zeros += 1;
                } else {
                    nonzero.push(ln_gamma(f64::from(n) + beta));
                }
            }
            terms.push(-ln_gamma(f64::from(self.n_k[t]) + v_beta));
        }
        terms.push(k as f64 * ln_gamma(v_beta));
        // K·V·lnΓ(β) less the zero entries, which would each add it back.
        terms.push(-((k * v - zeros) as f64) * ln_gamma_beta);
        terms.push(sum_iter(nonzero));
        sum_iter(terms)
    }

    /// `log p(z)` under the symmetric `Dirichlet(α)` document prior.
    fn log_prior(&self, alpha: f64) -> f64 {
        let k = self.k;
        let k_alpha = k as f64 * alpha;
        let d = self.n_d.len() as f64;
        let mut terms = vec![d * (ln_gamma(k_alpha) - k as f64 * ln_gamma(alpha))];
        for (row, &nd) in self.n_dk.chunks(k).zip(&self.n_d) {
            for &n in row {
                terms.push(ln_gamma(f64::from(n) + alpha));
            }
            terms.push(-ln_gamma(f64::from(nd) + k_alpha));
        }
        sum_iter(terms)
    }
}

/// The first index whose cumulative weight exceeds `u` (the last index if
/// rounding leaves `u` at or beyond the total).
fn draw(cumulative: &[f64], u: f64) -> usize {
    cumulative.iter().position(|&c| u < c).unwrap_or(cumulative.len() - 1)
}

fn validate_options(options: &TopicModelOptions) -> Result<()> {
    if options.topics == 0 {
        return Err(invalid("the number of topics must be at least 1".into()));
    }
    check_prior("alpha", options.alpha)?;
    check_prior("beta", options.beta)?;
    if options.iterations == 0 {
        return Err(invalid("the number of iterations must be at least 1".into()));
    }
    if options.thin == 0 {
        return Err(invalid("the thinning interval must be at least 1".into()));
    }
    Ok(())
}

fn check_prior(name: &str, value: f64) -> Result<()> {
    if value.is_finite() && value > 0.0 {
        Ok(())
    } else {
        Err(invalid(format!("{name} must be positive and finite, got {value}")))
    }
}

fn check_terms(documents: &[Vec<usize>], n_terms: usize) -> Result<()> {
    for (d, doc) in documents.iter().enumerate() {
        if let Some(&w) = doc.iter().find(|&&w| w >= n_terms) {
            return Err(invalid(format!("term id {w} in document {d} is not below the vocabulary size {n_terms}")));
        }
    }
    Ok(())
}

fn invalid(message: String) -> StatError {
    StatError::InvalidArgument { message }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tiny() -> (Vec<Vec<usize>>, Vec<Vec<usize>>) {
        (
            vec![vec![0, 1, 2, 1], vec![2, 3, 3], vec![], vec![0, 3, 1]],
            vec![vec![0, 1, 2, 1], vec![2, 0, 0], vec![], vec![1, 1, 2]],
        )
    }

    /// The sampler's full conditional equals the ratio of joint
    /// probabilities `p(w, z)` with `z_i` set to each topic, computed from
    /// the closed-form marginals.
    #[test]
    fn full_conditional_matches_brute_force_joint() {
        let (docs, z) = tiny();
        let (v, k) = (4, 3);
        for &(alpha, beta) in &[(0.5, 0.1), (2.0, 1.5), (0.05, 0.01)] {
            for d in 0..docs.len() {
                for i in 0..docs[d].len() {
                    // Brute force: log p(w, z) for each value of z_i.
                    let joint: Vec<f64> = (0..k)
                        .map(|t| {
                            let mut zt = z.clone();
                            zt[d][i] = t;
                            log_likelihood_of(&docs, &zt, v, k, beta).unwrap()
                                + log_prior_of(&docs, &zt, k, alpha).unwrap()
                        })
                        .collect();
                    let top = joint.iter().copied().fold(f64::NEG_INFINITY, f64::max);
                    let exp: Vec<f64> = joint.iter().map(|l| (l - top).exp()).collect();
                    let norm: f64 = exp.iter().sum();
                    // Sampler: counts with token i removed.
                    let mut state = State::from_assignments(&docs, &z, v, k).unwrap();
                    let (w, old) = (docs[d][i], z[d][i]);
                    state.n_dk[d * k + old] -= 1;
                    state.n_wk[w * k + old] -= 1;
                    state.n_k[old] -= 1;
                    let mut weights = vec![0.0; k];
                    let inverse: Vec<f64> = state.n_k.iter().map(|&n| 1.0 / (f64::from(n) + v as f64 * beta)).collect();
                    let total = full_conditional(
                        &state.n_dk[d * k..(d + 1) * k],
                        &state.n_wk[w * k..(w + 1) * k],
                        &inverse,
                        alpha,
                        beta,
                        &mut weights,
                    );
                    for t in 0..k {
                        let a = (weights[t] - if t == 0 { 0.0 } else { weights[t - 1] }) / total;
                        let b = exp[t] / norm;
                        assert!((a - b).abs() <= 1e-12 * b.max(1e-300), "d {d} i {i} k {t}: {a} vs {b}");
                    }
                }
            }
        }
    }

    #[test]
    fn draw_picks_interval() {
        let w = [1.0, 3.0, 6.0];
        assert_eq!(draw(&w, 0.0), 0);
        assert_eq!(draw(&w, 0.999), 0);
        assert_eq!(draw(&w, 1.0), 1);
        assert_eq!(draw(&w, 5.9), 2);
        assert_eq!(draw(&w, 6.0), 2);
    }

    fn small_corpus() -> Vec<Vec<usize>> {
        let mut rng = Rng::new(7);
        (0..30)
            .map(|d| {
                let base = if d % 2 == 0 { 0 } else { 5 };
                (0..20).map(|_| base + rng.below(5)).collect()
            })
            .collect()
    }

    #[test]
    fn deterministic_and_well_formed() {
        let mut docs = small_corpus();
        docs.push(Vec::new());
        let options = TopicModelOptions { iterations: 60, burn_in: 20, thin: 5, ..TopicModelOptions::new(3) };
        let a = fit_topic_model(&docs, 12, &options).unwrap();
        let b = fit_topic_model(&docs, 12, &options).unwrap();
        assert_eq!(a, b);
        let c = fit_topic_model(&docs, 12, &TopicModelOptions { seed: 2, ..options.clone() }).unwrap();
        assert_ne!(a.assignments, c.assignments);
        assert_eq!(a.samples, 8);
        assert_eq!(a.topic_term.len(), 3);
        for row in &a.topic_term {
            assert_eq!(row.len(), 12);
            assert!((row.iter().sum::<f64>() - 1.0).abs() < 1e-12);
        }
        for row in &a.document_topic {
            assert!((row.iter().sum::<f64>() - 1.0).abs() < 1e-12);
        }
        // The empty document keeps the prior mean.
        for &p in a.document_topic.last().unwrap() {
            assert!((p - 1.0 / 3.0).abs() < 1e-15);
        }
        assert!(a.topic_tokens.windows(2).all(|w| w[0] >= w[1]));
        assert_eq!(a.topic_tokens.iter().sum::<usize>(), 600);
        // Assignments agree with the reported token counts.
        let mut counts = [0usize; 3];
        for &t in a.assignments.iter().flatten() {
            counts[t] += 1;
        }
        assert_eq!(counts.to_vec(), a.topic_tokens);
        let sweeps: Vec<usize> = a.log_likelihood.iter().map(|p| p.0).collect();
        assert_eq!(sweeps, vec![0, 10, 20, 30, 40, 50, 60]);
        // The final trace value is the likelihood of the final assignments.
        let last = log_likelihood_of(&docs, &a.assignments, 12, 3, options.beta).unwrap();
        assert!((a.log_likelihood.last().unwrap().1 - last).abs() < 1e-9 * last.abs());
        // Terms 10, 11 never occur, so they are never top terms of a used topic.
        let top = a.top_terms(0, 5);
        assert_eq!(top.len(), 5);
        assert!(top.windows(2).all(|w| w[0].1 >= w[1].1));
        assert!(top.iter().all(|&(w, _)| w < 10));
        assert!(a.top_terms(3, 5).is_empty());
        assert_eq!(a.top_terms(0, 100).len(), 12);
    }

    #[test]
    fn burn_in_beyond_iterations_uses_last_state() {
        let docs = small_corpus();
        let options = TopicModelOptions { iterations: 15, burn_in: 15, ..TopicModelOptions::new(2) };
        let fit = fit_topic_model(&docs, 10, &options).unwrap();
        assert_eq!(fit.samples, 1);
        let est = estimates_from_assignments(&docs, &fit.assignments, 10, 2, options.alpha, options.beta).unwrap();
        assert_eq!(fit.topic_term, est.topic_term);
        assert_eq!(fit.document_topic, est.document_topic);
        assert_eq!(fit.log_likelihood.last().unwrap().0, 15);
    }

    #[test]
    fn learns_two_separated_topics() {
        let docs = small_corpus();
        let options = TopicModelOptions { alpha: 0.5, iterations: 200, burn_in: 100, ..TopicModelOptions::new(2) };
        let fit = fit_topic_model(&docs, 10, &options).unwrap();
        for row in &fit.topic_term {
            let low: f64 = row[..5].iter().sum();
            assert!(!(0.05..=0.95).contains(&low), "topic not separated: {low}");
        }
        let first = fit.log_likelihood[0].1;
        let last = fit.log_likelihood.last().unwrap().1;
        assert!(last > first);
        let perplexity = fit.perplexity(&docs).unwrap();
        // Ten equally used terms, five per topic: the ideal perplexity is 5.
        assert!(perplexity > 4.5 && perplexity < 5.5, "{perplexity}");
    }

    #[test]
    fn rejects_invalid_input() {
        let docs = vec![vec![0, 1], vec![]];
        let ok = TopicModelOptions::new(2);
        let fails = |docs: &[Vec<usize>], v, o: &TopicModelOptions| fit_topic_model(docs, v, o).is_err();
        assert!(fails(&docs, 2, &TopicModelOptions::new(0)));
        assert!(fails(&docs, 1, &ok));
        assert!(fails(&docs, 2, &TopicModelOptions { alpha: 0.0, ..ok.clone() }));
        assert!(fails(&docs, 2, &TopicModelOptions { alpha: -1.0, ..ok.clone() }));
        assert!(fails(&docs, 2, &TopicModelOptions { beta: 0.0, ..ok.clone() }));
        assert!(fails(&docs, 2, &TopicModelOptions { beta: f64::NAN, ..ok.clone() }));
        assert!(fails(&docs, 2, &TopicModelOptions { iterations: 0, ..ok.clone() }));
        assert!(fails(&docs, 2, &TopicModelOptions { thin: 0, ..ok.clone() }));
        assert!(matches!(
            fit_topic_model(&[vec![], vec![]], 3, &ok),
            Err(StatError::InsufficientData { required: 1, found: 0 })
        ));
        assert!(matches!(fit_topic_model(&[], 3, &ok), Err(StatError::InsufficientData { .. })));
        assert!(matches!(fit_topic_model(&docs, 1, &ok), Err(StatError::InvalidArgument { .. })));
        assert!(log_likelihood_of(&docs, &[vec![0], vec![]], 2, 2, 0.1).is_err());
        assert!(log_likelihood_of(&docs, &[vec![0, 2], vec![]], 2, 2, 0.1).is_err());
        assert!(log_likelihood_of(&docs, &[vec![0, 1]], 2, 2, 0.1).is_err());
        let fit = fit_topic_model(&docs, 2, &TopicModelOptions { iterations: 5, ..ok }).unwrap();
        assert!(fit.perplexity(&[vec![0]]).is_err());
        assert!(fit.perplexity(&[vec![0, 5], vec![]]).is_err());
        assert!(fit.perplexity(&[vec![], vec![]]).is_err());
    }
}
